class Solution {
public:
    TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {
        int n = preorder.size();
        unordered_map<int,int> idx;
        idx.reserve(n * 2);
        for (int i = 0; i < n; ++i) idx[inorder[i]] = i;
        int prePos = 0;
        return build(preorder, 0, n, prePos, idx);
    }
private:
    TreeNode* build(const vector<int>& preorder, int l, int r,
                    int& prePos, const unordered_map<int,int>& idx) {
        if (l >= r) return nullptr;
        int rootVal = preorder[prePos++];
        TreeNode* node = new TreeNode(rootVal);
        int i = idx.at(rootVal);          // split point in inorder
        node->left  = build(preorder, l, i, prePos, idx);
        node->right = build(preorder, i + 1, r, prePos, idx);
        return node;
    }
};
